keydown.code:
function keydown(event) {
  if (event.key === 'ArrowDown' && filtered.value.length) {
    event.preventDefault()
    activeIndex.value = Math.min(activeIndex.value + 1, filtered.value.length - 1)
    return
  }
  if (event.key === 'ArrowUp' && filtered.value.length) {
    event.preventDefault()
    activeIndex.value = Math.max(activeIndex.value - 1, 0)
    return
  }
  if (event.key === 'Escape') { open.value = false; return }
  if (event.key !== 'Enter') return
  // A combo value is part of the form, not a request to submit the whole form.
  event.preventDefault()
  if (props.multiple) { append(text.value); return }
  const value = normalize(text.value).trim()
  if (!value) return
  const matchingOption = filtered.value[activeIndex.value] || props.options.find(option => option.label === value || String(option.value) === value)
  if (matchingOption) choose(matchingOption)
  else if (props.allowCustom) choose({ value, label: value })
}

