function parseTraits(text) {
  const result = {}
  for (const line of text.split('\n').filter(v => v.trim())) {
    const parts = line.split(/[:：]/); const key = parts.shift().trim()
    if (!key || !parts.length) throw new Error('供货特点请每行填写“名称：内容”。')
    result[key] = parts.join('：').trim()
  }
  return result
}

